"use client";

/**
 * Client-side Amplify configuration for ivyshop International.
 * Import this in the root layout to configure Amplify before any API calls.
 * The ssr: true flag stores tokens in cookies for Next.js SSR.
 */

import { Amplify } from "aws-amplify";

// amplify_outputs.json is generated by Amplify Hosting CI/CD or sandbox.
// It is NOT committed to source control.
// During local development, run: npx ampx sandbox
let outputs: Record<string, unknown> = {};

try {
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  outputs = require("../../../amplify_outputs.json");
} catch {
  // amplify_outputs.json not yet generated — will be available after deployment
  console.warn(
    "amplify_outputs.json not found. Run `npx ampx sandbox` to generate it."
  );
}

if (Object.keys(outputs).length > 0) {
  Amplify.configure(outputs as Parameters<typeof Amplify.configure>[0], {
    ssr: true,
  });
}
